let playoffTab='bracket';
function playoffGames(){return state.history.filter(g=>g.stage==='Semifinal'||g.stage==='Championship')}
function playoffField(){const semis=playoffGames().filter(g=>g.stage==='Semifinal').reverse();return semis.length===2?[semis[0].a,semis[1].a,semis[1].b,semis[0].b].map(id=>state.teams[id]):rank().slice(0,4)}
function switchPlayoffTab(tab){if(!['bracket','games','teams','players','champions'].includes(tab))return;playoffTab=tab;render()}
function playoffMatch(ids,title,game){return `<section class="po-match"><h3>${title}</h3>${ids.map((id,i)=>{const t=state.teams[id],seed=(typeof usesConferencePlayoffs==='function'&&usesConferencePlayoffs()?conferencePlayoffGroups().find(g=>g.name===t?.conference)?.teams||[]:playoffField()).findIndex(p=>p.id===id)+1;return t?`<div class="po-team ${game?.winner===id?'po-winner':''}"><small>${seed||'—'}</small>${secondaryTeamLogo(t)}<span>${escapeHTML(t.city+' '+t.name)}<small>${t.w}–${t.l} regular season</small></span><b>${game?(game.a===id?game.sa:game.sb):'—'}</b></div>`:`<div class="po-team po-pending"><span>Winner of previous round</span><b>—</b></div>`}).join('')}${game?`<button onclick="showResult(${state.history.indexOf(game)})">View results ↗</button>`:'<p class="muted">'+(state.day<seasonLength()?'Projected matchup':'Awaiting tip-off')+'</p>'}</section>`}
function playoffBracket(){const top=playoffField(),games=playoffGames(),semi=(a,b)=>games.find(g=>g.stage==='Semifinal'&&g.a===a&&g.b===b),s1=semi(top[0].id,top[3].id),s2=semi(top[1].id,top[2].id),final=games.find(g=>g.stage==='Championship');return `<section class="po-panel"><h2>PLAYOFF BRACKET <small>${state.year} · ${state.day<seasonLength()?'Projected seeds':'Final seeds'}</small></h2><div class="po-bracket"><div>${playoffMatch([top[0].id,top[3].id],'SEMIFINAL 1 · #1 vs #4',s1)}</div><div class="po-final"><div class="po-cup">${gmIcon('trophy')}</div>${playoffMatch(final?[final.a,final.b]:[s1?.winner,s2?.winner],'CHAMPIONSHIP',final)}</div><div>${playoffMatch([top[1].id,top[2].id],'SEMIFINAL 2 · #2 vs #3',s2)}</div></div></section>`}
function playoffStats(players=false){const games=playoffGames();if(!games.length)return '<section class="po-panel"><h2>'+ (players?'PLAYER STATS':'TEAM STATS')+'</h2><p>Playoff statistics appear after the first postseason game.</p></section>';let rows=[];if(players){const map=new Map();for(const g of games)for(const p of g.box){if(p.played===false||p.mp===0)continue;const key=p.playerId??p.team+':'+p.name;const r=map.get(key)||{name:p.name,team:p.team,gp:0,pts:0,reb:0,ast:0};r.gp++;r.pts+=p.pts;r.reb+=p.reb;r.ast+=p.ast;map.set(key,r)}rows=[...map.values()].sort((a,b)=>b.pts/b.gp-a.pts/a.gp).map(r=>`<tr><th>${escapeHTML(r.name)} <small>${escapeHTML(r.team)}</small></th><td>${r.gp}</td><td>${(r.pts/r.gp).toFixed(1)}</td><td>${(r.reb/r.gp).toFixed(1)}</td><td>${(r.ast/r.gp).toFixed(1)}</td></tr>`)}else rows=playoffField().map(t=>{const gs=games.filter(g=>g.a===t.id||g.b===t.id),w=gs.filter(g=>g.winner===t.id).length;return `<tr><th><span class="po-stat-team">${secondaryTeamLogo(t)}${escapeHTML(t.city+' '+t.name)}</span></th><td>${w}–${gs.length-w}</td><td>${gs.length?(gs.reduce((n,g)=>n+(g.a===t.id?g.sa:g.sb),0)/gs.length).toFixed(1):'—'}</td><td>${gs.length?(gs.reduce((n,g)=>n+(g.a===t.id?g.sb:g.sa),0)/gs.length).toFixed(1):'—'}</td></tr>`});return `<section class="po-panel"><h2>${players?'PLAYER':'TEAM'} STATS <small>Postseason only</small></h2><div class="po-scroll"><table><thead><tr>${(players?['Player','GP','PPG','RPG','APG']:['Team','Record','PPG','OPPG']).map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div></section>`}
function playoffChampions(){const records=[...(state.championsArchive||[])];if(state.champion!==null&&!records.some(r=>r.year===state.year)){const t=state.teams[state.champion];records.push({year:state.year,name:t.city+' '+t.name})}return '<section class="po-panel"><h2>CHAMPIONS</h2>'+ (records.length?records.sort((a,b)=>b.year-a.year).map(r=>'<div class="po-champion"><b>'+r.year+'</b><span>'+escapeHTML(r.name)+'</span>'+gmIcon('trophy')+'</div>').join(''):'<p>No recorded champions yet. Future champions will be kept here across seasons.</p>')+'</section>'}
function playoffOdds(){const top=playoffField(),win=(a,b)=>1/(1+Math.exp((strength(b)-strength(a))/8)),opponents=[3,2,1,0];return top.map((t,i)=>{const others=[0,1,2,3].filter(j=>j!==i&&j!==opponents[i]);const chance=state.champion!==null?(state.champion===t.id?1:0):win(t,top[opponents[i]])*others.reduce((n,j)=>n+win(top[j],top[opponents[j]])*win(t,top[j]),0);return {t,chance}}).sort((a,b)=>b.chance-a.chance)}
function playoffsView(){if(!['bracket','games','teams','players','champions'].includes(playoffTab))playoffTab='bracket';const remaining=seasonLength()-state.day,champion=state.champion===null?null:state.teams[state.champion],games=playoffGames();const content=playoffTab==='bracket'?playoffBracket():playoffTab==='teams'?playoffStats():playoffTab==='players'?playoffStats(true):playoffTab==='champions'?playoffChampions():`<section class="po-panel"><h2>PLAYOFF GAMES</h2>${games.length?'<div class="po-games">'+[...games].reverse().map(g=>playoffMatch([g.a,g.b],g.stage.toUpperCase(),g)).join(''):'<p>Two semifinals. One championship game. Results will appear here after simulation.</p>'}</section>`;return `<div class="playoffs-page">${pageHeaderFor('Playoffs')}<nav class="po-tabs" aria-label="Playoff views">${[['bracket','Playoff bracket'],['games','Games'],['teams','Team stats'],['players','Player stats'],['champions','Past champions']].map(([id,label])=>`<button aria-pressed="${playoffTab===id}" class="${playoffTab===id?'selected':''}" onclick="switchPlayoffTab('${id}')">${label}</button>`).join('')}</nav><section class="po-summary"><div><small>POSTSEASON</small><strong>${remaining>0?'In '+remaining+' days':champion?'Complete':'Ready to tip off'}</strong><span>${remaining>0?'Seeds update with standings':'Regular season complete'}</span></div><div><small>TEAMS</small><strong>4</strong><span>Top four league-wide</span></div><div><small>FORMAT</small><strong>Single elimination</strong><span>Two rounds · Three games</span></div><div><small>${champion?'CHAMPION':'YOUR TEAM'}</small><strong class="po-stat-team">${secondaryTeamLogo(champion||team())}${escapeHTML((champion||team()).name)}</strong><span>${champion?'Championship secured':remaining>0?'#'+(rank().findIndex(t=>t.id===controlledTeamId())+1)+' in the playoff race':playoffField().some(t=>t.id===controlledTeamId())?'Qualified':'Eliminated'}</span></div></section><div class="po-actions">${remaining===0?`<button class="primary" onclick="${champion?'newSeason()':'playoffs()'}">${champion?'Continue offseason':'Simulate playoffs'} →</button>`:'<p>Finish the regular season to lock the bracket and simulate the playoffs.</p>'}</div>${content}<div class="po-bottom"><section class="po-panel"><h2>${champion?'FINAL OUTCOME':'TITLE CHANCES'}</h2>${playoffOdds().map(({t,chance})=>`<div class="po-odds"><span class="po-stat-team">${secondaryTeamLogo(t)}${escapeHTML(t.city+' '+t.name)}</span><b>${(chance*100).toFixed(1)}%</b></div>`).join('')}<p class="po-muted">${champion?'Final championship result.':'Rating-based estimates for the projected four-team field; not betting odds.'}</p></section><section class="po-panel"><h2>POSTSEASON ROADMAP</h2><div class="po-roadmap"><span>${gmIcon('calendar')}</span><div><strong>Regular season ends</strong><p>${scheduleDateLabel(seasonLength(),true)}</p></div></div><div class="po-roadmap"><span>${gmIcon('users')}</span><div><strong>Semifinals</strong><p>#1 vs #4 · #2 vs #3</p></div></div><div class="po-roadmap"><span>${gmIcon('trophy')}</span><div><strong>Championship</strong><p>Semifinal winners · Winner takes the title</p></div></div></section></div></div>`}
function archivePlayoffChampion(){if(state.champion===null)return;state.championsArchive??=[];if(state.championsArchive.some(r=>r.year===state.year))return;const t=state.teams[state.champion];state.championsArchive.push({year:state.year,name:t.city+' '+t.name});state.championsArchive=state.championsArchive.slice(-100)}
function readChampionsArchive(raw,bad){if(raw===undefined)return [];if(!Array.isArray(raw)||raw.length>100||raw.some(r=>!r||!Number.isInteger(r.year)||r.year<1900||r.year>10000||typeof r.name!=='string'||!r.name.trim()||r.name.length>100)||new Set(raw.map(r=>r.year)).size!==raw.length)bad('invalid champions archive.');return raw.map(r=>({year:r.year,name:r.name}))}
